const ASSETS = {"/app.js":{"type":"text/javascript; charset=utf-8","body":"const focusToggle = document.querySelector('#focusToggle');\nfocusToggle?.addEventListener('click', () => {\n  document.body.classList.toggle('focus-mode');\n  const active = document.body.classList.contains('focus-mode');\n  focusToggle.textContent = active ? '退出专注模式' : '开启专注模式';\n  if (active) document.querySelector('#core')?.scrollIntoView();\n});\n\nconst escapeHTML = (value) => String(value)\n  .replaceAll('&', '&amp;')\n  .replaceAll('<', '&lt;')\n  .replaceAll('>', '&gt;')\n  .replaceAll('\"', '&quot;')\n  .replaceAll(\"'\", '&#039;');\n\ndocument.querySelectorAll('details[data-review]').forEach((item) => {\n  const note = window.RESEARCH_REVIEWS?.[item.dataset.review];\n  if (!note) return;\n  const summary = item.querySelector('summary');\n  const contributions = note.contributions\n    .map((entry, index) => `<li><span>${String(index + 1).padStart(2, '0')}</span><p>${escapeHTML(entry)}</p></li>`)\n    .join('');\n\n  item.innerHTML = '';\n  item.append(summary);\n  item.insertAdjacentHTML('beforeend', `\n    <div class=\"review-sheet\">\n      <div class=\"review-kicker\"><span>FULL-TEXT NOTES</span><p>以下判断来自方法、结果、讨论与局限部分的全文核验，不是摘要改写。</p></div>\n      <div class=\"review-pair\">\n        <section class=\"review-block\"><b>01</b><div><h4>研究问题</h4><p>${escapeHTML(note.problem)}</p></div></section>\n        <section class=\"review-block\"><b>02</b><div><h4>方法与样本</h4><p>${escapeHTML(note.method)}</p></div></section>\n      </div>\n      <section class=\"review-contributions\">\n        <div class=\"review-title\"><b>03</b><h4>主要贡献</h4><span>作者实际交付了什么</span></div>\n        <ol>${contributions}</ol>\n      </section>\n      <section class=\"review-delta\">\n        <div class=\"review-title\"><b>04</b><h4>相较以往的 delta</h4><span>过去做法 → 本文改变 → 仍需付出的代价</span></div>\n        <p>${escapeHTML(note.delta)}</p>\n      </section>\n      <div class=\"review-pair judgement\">\n        <section class=\"review-block evidence\"><b>05</b><div><h4>证据够不够</h4><p>${escapeHTML(note.evidence)}</p></div></section>\n        <section class=\"review-block limitations\"><b>06</b><div><h4>局限与不可外推之处</h4><p>${escapeHTML(note.limitations)}</p></div></section>\n      </div>\n      <div class=\"review-bottom\">\n        <section><span>WHY READ</span><h4>为什么值得你读</h4><p>${escapeHTML(note.whyRead)}</p></section>\n        <section><span>READING PATH</span><h4>如果打开原文，优先看这里</h4><p>${escapeHTML(note.readingPath)}</p></section>\n      </div>\n    </div>`);\n});\n\ndocument.querySelectorAll('details').forEach((item) => {\n  item.addEventListener('toggle', () => {\n    if (!item.open) return;\n    const section = item.closest('.paper-section');\n    section?.querySelectorAll('details[open]').forEach((other) => {\n      if (other !== item) other.open = false;\n    });\n  });\n});\n"},"/archive/2026-11-10/index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Research Daily · 2026-11-10</title><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link href=\"https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Noto+Sans+SC:wght@400;500;600;700;900&family=Noto+Serif+SC:wght@600;700;900&display=swap\" rel=\"stylesheet\"><link rel=\"stylesheet\" href=\"../../styles.css\"></head>\n<body><header class=\"masthead\"><a class=\"brand\" href=\"../\"><span class=\"brand-mark\">RD</span><span><strong>RESEARCH DAILY</strong><small>FULL-TEXT REVIEWED</small></span></a><div class=\"issue\"><a class=\"archive-link\" href=\"../\">综合目录</a>&nbsp;&nbsp;·&nbsp;&nbsp;2026-11-10</div></header>\n<main><section class=\"hero archive-hero\"><div class=\"hero-copy\"><p class=\"eyebrow\">PERMANENT DAILY EDITION</p><h1>2026-11-10<br><em>学术早报</em></h1><p class=\"dek\">共 6 篇，建议阅读 31 分钟。此页面按日期永久保存，后续早报不会覆盖本期内容。</p><div class=\"hero-actions\"><a class=\"primary\" href=\"#core\">开始阅读 <span>↓</span></a><a class=\"ghost archive-button\" href=\"../\">查看全部日期</a></div></div><aside class=\"reading-map\"><div class=\"map-head\"><span>ARCHIVED EDITION</span><strong>31<span>MIN</span></strong></div><p class=\"archive-count\">6 篇全文核验论文<br>推荐记录已写入永久去重账本</p></aside></section>\n<section class=\"priority\"><div class=\"priority-label\"><span>IF YOU ONLY READ TWO</span><b>只读两篇</b></div><a href=\"#paper-p_1e363db76b43e7ce\"><span>01</span><strong>让语言模型先拆问题、写代码算个人可穿戴数据、出错后再重试，比一次性给答案可靠得多；但这篇论文证明的是“答题能力”，不是这些建议真的能改善健康。</strong><i>6 min ↗</i></a><a href=\"#paper-p_e1401bb657deafba\"><span>02</span><strong>这块手表不尝试报出你此刻的血压，而是连续看一周的脉搏光学信号和动作，判断你是否可能长期偏高；它比一次门诊测量多抓到一些人，但仍漏掉约三分之一病例。</strong><i>6 min ↗</i></a></section><section class=\"paper-section core\" id=\"core\"><header class=\"section-head\"><div><span class=\"section-no\">01</span><p>PRIMARY SIGNAL</p></div><h2>主要相关</h2><p>本期内容已阅读全文并永久归档。</p></header>\n        <article class=\"paper\" id=\"paper-p_1e363db76b43e7ce\">\n          <div class=\"paper-index\">01</div>\n          <div class=\"paper-main\">\n            <div class=\"meta\"><span>Nature Communications · 2026</span><span>6 MIN</span><span>OpenAlex 引用 78 · 2026-11-10</span></div>\n            <h3>Transforming wearable data into personal health insights using large language model agents</h3>\n            <p class=\"authors\">Mike A. Merrill、Akshay Paruchuri、Naghmeh Rezaei、Geza Kovacs、Javier Perez、Yun Liu、Erik Schenck、Nova Hammerquist、Jake Sunshine、Shyam A. Tailor、Kumar Ayush、Hao-Wei Su、Qian He、Cory Y. McLean、Mark Malhotra、Shwetak Patel、Jiening Zhan、Tim Althoff、Daniel McDuff、Xin Liu</p>\n            <div class=\"plain\"><small>说人话</small><p>让语言模型先拆问题、写代码算个人可穿戴数据、出错后再重试，比一次性给答案可靠得多；但这篇论文证明的是“答题能力”，不是这些建议真的能改善健康。</p></div>\n            <details><summary>展开完整精读笔记 <span>+</span></summary>\n              <div class=\"review-sheet\">\n                <div class=\"review-kicker\"><span>FULL-TEXT NOTES</span><p>来自方法、结果、讨论与局限部分的全文核验，不是摘要改写。</p></div>\n                <div class=\"review-pair\">\n                  <section class=\"review-block\"><b>01</b><div><h4>研究问题</h4><p>像“运动后的睡眠是否更好”这类个人健康问题既需要准确计算时间序列，又需要结合背景知识。纯文本推理容易算错，单次代码生成也无法发现并修复自己的错误。</p></div></section>\n                  <section class=\"review-block\"><b>02</b><div><h4>方法与样本</h4><p>PHIA 把规划、Python 数据分析和网页检索组合成多步 agent。作者构建了 4000 多个封闭式和开放式问题，用来源于 3 万名同意参与研究的 Fitbit/Pixel Watch 用户数据训练生成器并合成 56 个虚拟用户，抽取 4 个做客观评估；开放问题由多人盲评，累计约 650 小时人工评估。</p></div></section>\n                </div>\n                <section class=\"review-contributions\"><div class=\"review-title\"><b>03</b><h4>主要贡献</h4><span>作者实际交付了什么</span></div><ol><li><span>01</span><p>提出一个针对个人可穿戴时间序列的 agent 工作流，可反复生成代码、检查结果、检索背景知识并修正错误。</p></li><li><span>02</span><p>发布高保真合成可穿戴数据和 4000 多题的个人健康洞察评测集，降低真实个人数据的隐私风险。</p></li><li><span>03</span><p>在客观问题上达到 84% 准确率；代码错误率为 0.192，而单次代码生成基线为 0.395，并展示了非零的自我恢复能力。</p></li></ol></section>\n                <section class=\"review-delta\"><div class=\"review-title\"><b>04</b><h4>相较以往的 delta</h4><span>过去做法 → 本文改变 → 仍需付出的代价</span></div><p>以往工作多把汇总后的可穿戴指标直接塞进模型，或让模型一次生成代码；PHIA 把问题分解、代码执行、外部检索和迭代纠错串成闭环。真正的增量是可执行且能恢复的分析流程，而不是单纯换了更大的语言模型。</p></section>\n                <div class=\"review-pair judgement\">\n                  <section class=\"review-block evidence\"><b>05</b><div><h4>证据够不够</h4><p>同一底层模型下与数值推理、代码生成等基线比较，能较好隔离 agent 流程本身的作用；人工盲评规模也很大。可是客观评估主要依赖 4 个合成用户，开放问题由熟悉消费健康数据但不是临床医生的评审评价，且没有真实用户健康结局。</p></div></section>\n                  <section class=\"review-block limitations\"><b>06</b><div><h4>局限与不可外推之处</h4><p>没有证明用户会更理解数据、改变行为或获得临床收益；医学建议的真实性没有由临床专家系统评估；问题来源部分来自作者同事，可能不代表普通用户；合成数据虽保护隐私，但可能弱化真实世界的长尾缺失、设备故障和复杂共病。</p></div></section>\n                </div>\n                <div class=\"review-bottom\">\n                  <section><span>WHY READ</span><h4>为什么值得你读</h4><p>它正好连接 sensing、personal informatics 和 AI agent：展示了如何把连续传感数据从“模型输入”变成可追问、可计算、可审计的交互式分析对象。</p></section>\n                  <section><span>READING PATH</span><h4>如果打开原文，优先看这里</h4><p>先看 Fig. 7 的 agent 流程，再看 Fig. 1–4 的错误率与恢复率；最后精读 Discussion 的四项限制和 Synthetic wearable user data 方法。</p></section>\n                </div>\n              </div>\n            </details>\n            <div class=\"paper-links\"><a href=\"https://doi.org/10.1038/s41467-025-67922-y\" target=\"_blank\" rel=\"noreferrer\">论文页面 ↗</a><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC12855967/\" target=\"_blank\" rel=\"noreferrer\">阅读全文 ↗</a></div>\n          </div>\n          <aside class=\"why\"><span>PRIMARY SIGNAL</span><p>它正好连接 sensing、personal informatics 和 AI agent：展示了如何把连续传感数据从“模型输入”变成可追问、可计算、可审计的交互式分析对象。</p></aside>\n        </article>\n        <article class=\"paper\" id=\"paper-p_f5e81a6a7e372cdc\">\n          <div class=\"paper-index\">02</div>\n          <div class=\"paper-main\">\n            <div class=\"meta\"><span>Nature Communications · 2026</span><span>5 MIN</span><span>OpenAlex 引用 0 · 2026-11-10</span></div>\n            <h3>Silicon-photonics optoacoustic sensor for fully wearable blood pressure monitoring</h3>\n            <p class=\"authors\">Gil Gelbert、Ron Moisseev、Yoav Hazan、Tamar Harary、Daniel H. Lange、Amir Rosenthal</p>\n            <div class=\"plain\"><small>说人话</small><p>作者把原本需要多阵元、精确对准血管的超声方案，换成一个极小的光声探头；它重新贴到手腕上仍能跟踪血压波形，但人体实验目前只有两个人。</p></div>\n            <details><summary>展开完整精读笔记 <span>+</span></summary>\n              <div class=\"review-sheet\">\n                <div class=\"review-kicker\"><span>FULL-TEXT NOTES</span><p>来自方法、结果、讨论与局限部分的全文核验，不是摘要改写。</p></div>\n                <div class=\"review-pair\">\n                  <section class=\"review-block\"><b>01</b><div><h4>研究问题</h4><p>连续无袖带血压监测需要直接、稳定地测量动脉变化。现有 PPG 多为间接估计且容易受位置和个体差异影响，超声贴片虽然更直接，却依赖阵列和精确对准小动脉。</p></div></section>\n                  <section class=\"review-block\"><b>02</b><div><h4>方法与样本</h4><p>系统用硅光子声学探测器 SPADE 接收光激发动脉产生的光声信号，从信号时延估计桡动脉内径。作者先用仿体和多角度、位移实验验证位置鲁棒性，再在一男一女两名志愿者上进行 3 个月、120 段各 10 秒的测量，与 Finapres 袖带/指套参考系统比较；每人只在最初校准一次。</p></div></section>\n                </div>\n                <section class=\"review-contributions\"><div class=\"review-title\"><b>03</b><h4>主要贡献</h4><span>作者实际交付了什么</span></div><ol><li><span>01</span><p>用单个微型、近全向的硅光子探测元件替代密集超声阵列，直接读取动脉内腔边界。</p></li><li><span>02</span><p>在平移、旋转和反复移除重贴条件下展示较低的直径估计波动，说明方案对佩戴位置更宽容。</p></li><li><span>03</span><p>在两名被试的 120 次测量中得到舒张压 2.6 mmHg、收缩压 4.7 mmHg 的平均绝对差。</p></li></ol></section>\n                <section class=\"review-delta\"><div class=\"review-title\"><b>04</b><h4>相较以往的 delta</h4><span>过去做法 → 本文改变 → 仍需付出的代价</span></div><p>以往可穿戴超声依靠聚焦或多阵元找准血管，复杂度和位置敏感性随血管变小而增加；本文利用血液相对周围组织更强的光声对比度，加上微型近全向探测器，用单元件完成测量。代价是当前仍需要桌面激光器、耦合胶和个体初始校准。</p></section>\n                <div class=\"review-pair judgement\">\n                  <section class=\"review-block evidence\"><b>05</b><div><h4>证据够不够</h4><p>仿体、与压电探头的对照以及跨三个月重复贴附共同支持“位置鲁棒”这一工程主张；血压误差也有同步参考设备。不过临床数据只有两人，120 个短片段并不等于 120 个独立受试者，不能据此宣称达到普遍临床可用性。</p></div></section>\n                  <section class=\"review-block limitations\"><b>06</b><div><h4>局限与不可外推之处</h4><p>人体样本 n=2，主要在静坐和短暂核心发力状态下测试；每人仍需一次校准；参考系统本身有误差；装置尚包含体积较大的激光和光学读出，离真正日常佩戴还有明显工程距离。作者也明确承认需要超过 85 人的标准化临床验证。</p></div></section>\n                </div>\n                <div class=\"review-bottom\">\n                  <section><span>WHY READ</span><h4>为什么值得你读</h4><p>这是很典型的 sensing 系统论文：创新不是换一个分类器，而是利用新的物理对比机制改变对准、阵列规模和可穿戴化之间的设计空间。</p></section>\n                  <section><span>READING PATH</span><h4>如果打开原文，优先看这里</h4><p>重点看 Fig. 5 的旋转对照、Fig. 6 的血压验证，以及 Discussion 第 247–271 段对位置鲁棒性、n=2 和桌面激光器的坦诚讨论。</p></section>\n                </div>\n              </div>\n            </details>\n            <div class=\"paper-links\"><a href=\"https://doi.org/10.1038/s41467-026-77580-3\" target=\"_blank\" rel=\"noreferrer\">论文页面 ↗</a><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC13680363/\" target=\"_blank\" rel=\"noreferrer\">阅读全文 ↗</a></div>\n          </div>\n          <aside class=\"why\"><span>PRIMARY SIGNAL</span><p>这是很典型的 sensing 系统论文：创新不是换一个分类器，而是利用新的物理对比机制改变对准、阵列规模和可穿戴化之间的设计空间。</p></aside>\n        </article>\n        <article class=\"paper\" id=\"paper-p_1a21c67395ea6e02\">\n          <div class=\"paper-index\">05</div>\n          <div class=\"paper-main\">\n            <div class=\"meta\"><span>npj Biological Timing and Sleep · 2026</span><span>4 MIN</span><span>OpenAlex 引用 0 · 2026-11-10</span></div>\n            <h3>Five wearable sensors for objective measurement of near work and light exposure</h3>\n            <p class=\"authors\">Raman Prasad Sah、Nebee Yohannes、Pavan Narra、Lisa A. Ostrin</p>\n            <div class=\"plain\"><small>说人话</small><p>同一个人、同一天戴着五种设备，测出来的“近距离用眼时间”和室内光照仍会不一样；研究者选哪种传感器，会直接改变最后得到的行为结论。</p></div>\n            <details><summary>展开完整精读笔记 <span>+</span></summary>\n              <div class=\"review-sheet\">\n                <div class=\"review-kicker\"><span>FULL-TEXT NOTES</span><p>来自方法、结果、讨论与局限部分的全文核验，不是摘要改写。</p></div>\n                <div class=\"review-pair\">\n                  <section class=\"review-block\"><b>01</b><div><h4>研究问题</h4><p>近视研究越来越依赖可穿戴设备估计近距离用眼和光照，但不同佩戴位置、量程和采样方式的数据能否互相替代并不清楚，自我活动日志也可能系统性偏差。</p></div></section>\n                  <section class=\"review-block\"><b>02</b><div><h4>方法与样本</h4><p>30 名成年人在自然生活中连续约 14 小时同时佩戴两种眼镜式距离/光照传感器和三种腕式光照传感器，并填写活动日志。作者把距离和照度分箱，用配对的非参数统计比较设备间及设备与日志的一致性。</p></div></section>\n                </div>\n                <section class=\"review-contributions\"><div class=\"review-title\"><b>03</b><h4>主要贡献</h4><span>作者实际交付了什么</span></div><ol><li><span>01</span><p>在完全相同的被试和时间段内直接比较五种常用设备，避免跨研究、跨样本比较造成的混淆。</p></li><li><span>02</span><p>发现五种设备对强户外光照的判断较一致，但眼镜式设备对近距离和中距离用眼给出显著不同的时长分布。</p></li><li><span>03</span><p>证明活动日志会低估近距离用眼、并高估中距离用眼和部分户外时长，说明主观记录不能简单代替客观测量。</p></li></ol></section>\n                <section class=\"review-delta\"><div class=\"review-title\"><b>04</b><h4>相较以往的 delta</h4><span>过去做法 → 本文改变 → 仍需付出的代价</span></div><p>过去很多研究使用单一设备或自我日志，默认这些测量大致等价；本文让五种设备被同时佩戴，直接量化了设备选择带来的系统差异。增量不是新传感器，而是把“测量工具本身”当成需要验证的研究变量。</p></section>\n                <div class=\"review-pair judgement\">\n                  <section class=\"review-block evidence\"><b>05</b><div><h4>证据够不够</h4><p>同一被试同步佩戴使比较很干净，统计检验也报告了校正后的显著性和效应量。强户外光照的一致性结论可信；但由于没有真实观看距离和眼部照度的金标准，结果只能说明相互一致或不一致，不能判断哪台设备绝对更准。</p></div></section>\n                  <section class=\"review-block limitations\"><b>06</b><div><h4>局限与不可外推之处</h4><p>样本只有 30 名健康成年人、仅记录一天且都在休斯敦；没有实验室金标准；手腕遮挡、眼镜安装角度和各设备采样周期不同。部分设备由厂商提供，通讯作者披露了与 Meta、Zeiss 和相关专利的关系。</p></div></section>\n                </div>\n                <div class=\"review-bottom\">\n                  <section><span>WHY READ</span><h4>为什么值得你读</h4><p>它对 sensing 研究很实用：提醒我们在真实部署中，传感器位置、阈值和采样策略不是实现细节，而会改变行为标签与科学结论。</p></section>\n                  <section><span>READING PATH</span><h4>如果打开原文，优先看这里</h4><p>先看图 4–6 的同步轨迹和分箱结果，再看 Table 5 的设备规格，最后读 Discussion 中关于无金标准和设备差异的解释。</p></section>\n                </div>\n              </div>\n            </details>\n            <div class=\"paper-links\"><a href=\"https://doi.org/10.1038/s44323-026-00113-0\" target=\"_blank\" rel=\"noreferrer\">论文页面 ↗</a><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC13739900/\" target=\"_blank\" rel=\"noreferrer\">阅读全文 ↗</a></div>\n          </div>\n          <aside class=\"why\"><span>PRIMARY SIGNAL</span><p>它对 sensing 研究很实用：提醒我们在真实部署中，传感器位置、阈值和采样策略不是实现细节，而会改变行为标签与科学结论。</p></aside>\n        </article></section><section class=\"paper-section adjacent\" id=\"adjacent\"><header class=\"section-head\"><div><span class=\"section-no\">02</span><p>ADJACENT FIELD</p></div><h2>次要相关</h2><p>本期内容已阅读全文并永久归档。</p></header>\n        <article class=\"paper\" id=\"paper-p_4bee27f7d05ad6b3\">\n          <div class=\"paper-index\">03</div>\n          <div class=\"paper-main\">\n            <div class=\"meta\"><span>Frontiers in Robotics and AI · 2026</span><span>5 MIN</span><span>OpenAlex 引用 0 · 2026-11-10</span></div>\n            <h3>QAMQOR: a benchmark dataset for engagement recognition in robot-assisted autism therapy</h3>\n            <p class=\"authors\">Nazerke Rakhymbayeva、Aida Tungatarova、Zhansaule Telisheva、Anara Sandygulova</p>\n            <div class=\"plain\"><small>说人话</small><p>这篇论文最重要的发现不是某个模型更强，而是把同一个孩子或同一场治疗的视频同时放进训练集和测试集，会让结果看起来好得不真实。</p></div>\n            <details><summary>展开完整精读笔记 <span>+</span></summary>\n              <div class=\"review-sheet\">\n                <div class=\"review-kicker\"><span>FULL-TEXT NOTES</span><p>来自方法、结果、讨论与局限部分的全文核验，不是摘要改写。</p></div>\n                <div class=\"review-pair\">\n                  <section class=\"review-block\"><b>01</b><div><h4>研究问题</h4><p>机器人辅助孤独症治疗需要识别儿童是否投入互动，但公开数据少、样本小，很多论文随机切视频帧，导致同一儿童或同一会话泄漏到训练和测试两边。</p></div></section>\n                  <section class=\"review-block\"><b>02</b><div><h4>方法与样本</h4><p>QAMQOR 收集了 34 名 3–12 岁孤独症儿童与 NAO 机器人进行治疗活动的 187 个会话、约 47 小时视频，并提取脸、身体和手部姿态特征。作者定义随机、儿童独立、会话独立和活动独立四种划分，统一比较逻辑回归、树模型、时序 XGBoost、LSTM 和 TCN，并单独测试类别平衡。</p></div></section>\n                </div>\n                <section class=\"review-contributions\"><div class=\"review-title\"><b>03</b><h4>主要贡献</h4><span>作者实际交付了什么</span></div><ol><li><span>01</span><p>公开一个真实治疗环境中的参与度数据集，并随数据给出防泄漏的标准化划分。</p></li><li><span>02</span><p>量化评估协议的影响：多分类任务中，不同划分造成的 macro-F1 变化约 0.12，而可学习分类器之间只有约 0.07。</p></li><li><span>03</span><p>显示儿童独立划分接近机会水平，且在同等、未调参条件下，LSTM/TCN 没有优于简单树模型。</p></li></ol></section>\n                <section class=\"review-delta\"><div class=\"review-title\"><b>04</b><h4>相较以往的 delta</h4><span>过去做法 → 本文改变 → 仍需付出的代价</span></div><p>过去数据集往往只提供数据，论文各自随机划分并报告一个漂亮数字；QAMQOR 把“能否泛化到新儿童、新会话和新活动”写进基准协议。增量是把部署条件固化为评估制度，而不是再发明一个网络。</p></section>\n                <div class=\"review-pair judgement\">\n                  <section class=\"review-block evidence\"><b>05</b><div><h4>证据够不够</h4><p>34 名儿童、187 个真实会话比常见小型 HRI 实验更贴近部署，四种划分和多类模型能直接展示泄漏效应。结果也诚实地暴露了模型几乎不可用的儿童独立表现。但深度模型未专门调参，所以不能得出“深度学习无用”的一般结论。</p></div></section>\n                  <section class=\"review-block limitations\"><b>06</b><div><h4>局限与不可外推之处</h4><p>独立参与者仍只有 34 人，性别极不均衡（32 男、2 女），姿态按 1 fps 采样且主要使用视频关键点；行为和年龄异质性大，模型没有做个体校准；当前性能不足以让机器人对陌生儿童自动调整治疗。</p></div></section>\n                </div>\n                <div class=\"review-bottom\">\n                  <section><span>WHY READ</span><h4>为什么值得你读</h4><p>它是 HRI/sensing 评估设计的好例子：研究贡献可以是揭示数据切分比模型结构更重要，并把生态有效性写入 benchmark。</p></section>\n                  <section><span>READING PATH</span><h4>如果打开原文，优先看这里</h4><p>看 Table 2 的队列结构、四种 evaluation protocols、Fig. 5 与 Sections 5.2/5.6 的模型比较，以及 Discussion 6.1 对实际部署的解释。</p></section>\n                </div>\n              </div>\n            </details>\n            <div class=\"paper-links\"><a href=\"https://doi.org/10.3389/frobt.2026.1868211\" target=\"_blank\" rel=\"noreferrer\">论文页面 ↗</a><a href=\"https://www.frontiersin.org/journals/robotics-and-ai/articles/10.3389/frobt.2026.1868211/full\" target=\"_blank\" rel=\"noreferrer\">阅读全文 ↗</a></div>\n          </div>\n          <aside class=\"why\"><span>ADJACENT FIELD</span><p>它是 HRI/sensing 评估设计的好例子：研究贡献可以是揭示数据切分比模型结构更重要，并把生态有效性写入 benchmark。</p></aside>\n        </article></section><section class=\"paper-section landmark\" id=\"heavyweight\"><header class=\"section-head\"><div><span class=\"section-no\">03</span><p>LANDMARK READ</p></div><h2>重要文献</h2><p>本期内容已阅读全文并永久归档。</p></header>\n        <article class=\"paper\" id=\"paper-p_e1401bb657deafba\">\n          <div class=\"paper-index\">04</div>\n          <div class=\"paper-main\">\n            <div class=\"meta\"><span>Nature · 2026</span><span>6 MIN</span><span>OpenAlex 引用 1 · 2026-11-10</span></div>\n            <h3>Opportunistically Detecting Signs of Hypertension on a Consumer Smartwatch</h3>\n            <p class=\"authors\">Paolo Di Achille、Lawrence Cai、Jiang Wu、Mingwu Gao、Bhavna Daryani、Jonathan Wang、Utkarsh Khanna、Ho Ko、Anupam Pathak、Mark Malhotra、Shwetak Patel、Jacqueline B. Shreibati、Stephen P. Juraschek、Pramod Rudrapatna、Matthew Thompson、Ming-Zher Poh</p>\n            <div class=\"plain\"><small>说人话</small><p>这块手表不尝试报出你此刻的血压，而是连续看一周的脉搏光学信号和动作，判断你是否可能长期偏高；它比一次门诊测量多抓到一些人，但仍漏掉约三分之一病例。</p></div>\n            <details><summary>展开完整精读笔记 <span>+</span></summary>\n              <div class=\"review-sheet\">\n                <div class=\"review-kicker\"><span>FULL-TEXT NOTES</span><p>来自方法、结果、讨论与局限部分的全文核验，不是摘要改写。</p></div>\n                <div class=\"review-pair\">\n                  <section class=\"review-block\"><b>01</b><div><h4>研究问题</h4><p>高血压筛查依赖袖带，单次门诊测量会受白大衣效应影响，也会漏掉隐匿性高血压。过去无袖带方案常估计瞬时血压，受动作、接触压力和个体差异影响，并且常用家庭血压而非 24 小时动态血压作标签。</p></div></section>\n                  <section class=\"review-block\"><b>02</b><div><h4>方法与样本</h4><p>研究把 Pixel Watch 3 的 PPG 与加速度波形编码成个体表示，再用身高和逻辑回归判断高血压状态。前瞻性多中心队列在 5 个美国站点招募 296 人，196 人有完整门诊和 24 小时动态血压数据并进入分析；参与者在自由生活中佩戴手表约 7 天，并与动态血压、家庭血压和门诊血压逐一比较。</p></div></section>\n                </div>\n                <section class=\"review-contributions\"><div class=\"review-title\"><b>03</b><h4>主要贡献</h4><span>作者实际交付了什么</span></div><ol><li><span>01</span><p>把目标从估计某一时刻的收缩压/舒张压，改成从多日传感数据识别持续性高血压状态。</p></li><li><span>02</span><p>同时利用 PPG 和加速度波形，而不只是用加速度筛选静止片段，也不要求先用袖带为个人校准。</p></li><li><span>03</span><p>以 24 小时动态血压为金标准，得到 65.8% 灵敏度、90.0% 特异度和 80.6% 阳性预测值；单次门诊筛查对应为 55.3%、90.0% 和 77.8%。</p></li></ol></section>\n                <section class=\"review-delta\"><div class=\"review-title\"><b>04</b><h4>相较以往的 delta</h4><span>过去做法 → 本文改变 → 仍需付出的代价</span></div><p>此前无袖带研究多追求逐点血压数值，容易被波形噪声和校准拖累；本文退一步做长期状态筛查，并用自由生活的一周信号和动态血压真值验证。这个重构让消费手表更可能成为筛查入口，但它不是血压计，也不能完成诊断。</p></section>\n                <div class=\"review-pair judgement\">\n                  <section class=\"review-block evidence\"><b>05</b><div><h4>证据够不够</h4><p>前瞻、多中心、自由生活、与同一批人的 24 小时动态血压头对头比较，是很强的临床转化设计；肤色分布也较多样。另一方面，只有 196/296 人进入最终分析，缺失主要来自动态血压；灵敏度置信区间较宽，且 65.8% 本身说明漏诊仍多。</p></div></section>\n                  <section class=\"review-block limitations\"><b>06</b><div><h4>局限与不可外推之处</h4><p>排除了已知心血管病和正在服降压药的人，不能外推到治疗人群；只测试一种手表和美国站点；34% 招募者因数据不完整未进入主要分析；模型输出是风险提示而非诊断，尚未证明提示能改善就医、血压控制或心血管结局。阅读全文使用公开的 medRxiv 完整稿，并与 Nature 2026 年 11 月 5 日的同行评审早期版本题录和主要结果交叉核对。</p></div></section>\n                </div>\n                <div class=\"review-bottom\">\n                  <section><span>WHY READ</span><h4>为什么值得你读</h4><p>这是一篇 sensing 目标函数设计的代表作：与其硬做不稳定的连续回归，不如重新定义临床上真正有价值、且传感器能可靠承担的筛查任务。</p></section>\n                  <section><span>READING PATH</span><h4>如果打开原文，优先看这里</h4><p>优先看 prospective validation study、Fig. 1 的流程、与门诊/家庭血压的头对头结果、error analysis，以及 Discussion 中对缺失数据和适用人群的限制。</p></section>\n                </div>\n              </div>\n            </details>\n            <div class=\"paper-links\"><a href=\"https://doi.org/10.1038/s41586-026-11336-3\" target=\"_blank\" rel=\"noreferrer\">论文页面 ↗</a><a href=\"https://www.medrxiv.org/content/10.64898/2025.12.10.25341972v1.full\" target=\"_blank\" rel=\"noreferrer\">阅读全文 ↗</a></div>\n          </div>\n          <aside class=\"why\"><span>LANDMARK READ</span><p>这是一篇 sensing 目标函数设计的代表作：与其硬做不稳定的连续回归，不如重新定义临床上真正有价值、且传感器能可靠承担的筛查任务。</p></aside>\n        </article></section><section class=\"paper-section random\" id=\"serendipity\"><header class=\"section-head\"><div><span class=\"section-no\">04</span><p>SERENDIPITY</p></div><h2>随机看一篇</h2><p>本期内容已阅读全文并永久归档。</p></header>\n        <article class=\"paper\" id=\"paper-p_a2b9a04907675c47\">\n          <div class=\"paper-index\">06</div>\n          <div class=\"paper-main\">\n            <div class=\"meta\"><span>Nature Communications · 2026</span><span>5 MIN</span><span>OpenAlex 引用 0 · 2026-11-10</span></div>\n            <h3>A multiplexed wearable microfluidic platform for non-invasive sweat-inspired monitoring of plant guttation biomarkers</h3>\n            <p class=\"authors\">Bing Xue、Ziyang Huang、Zhiyuan Li、Xue Sun、Zhefu Shen、Junyi Luo、Kejing Ren、Wei Zhang、Ruochen Yang、Xiao Xiao、Xiaoqian Su、Shuoyan Liu、Anxu Ge、Jinghua Li、Ishara Dharmasena、Tedrick Thomas Salim Lew、Changsheng Wu</p>\n            <div class=\"plain\"><small>说人话</small><p>作者把人类汗液贴片的思路搬到了叶子上：设备接住植物自然渗出的微小液滴，连续测钾、钠和葡萄糖，让植物的盐胁迫和光照反应可以被实时看见。</p></div>\n            <details><summary>展开完整精读笔记 <span>+</span></summary>\n              <div class=\"review-sheet\">\n                <div class=\"review-kicker\"><span>FULL-TEXT NOTES</span><p>来自方法、结果、讨论与局限部分的全文核验，不是摘要改写。</p></div>\n                <div class=\"review-pair\">\n                  <section class=\"review-block\"><b>01</b><div><h4>研究问题</h4><p>植物内部液体能反映营养和胁迫，但传统方法需要穿刺或间歇取样；叶缘自然分泌的吐水液虽无创，却体积小、出现不连续且很快蒸发。</p></div></section>\n                  <section class=\"review-block\"><b>02</b><div><h4>方法与样本</h4><p>PlantIonics 用仿猪笼草表面的楔形亲/疏水微流道，在约 0.6 秒内把吐水液单向送到钾、钠、葡萄糖电化学传感阵列；0.16 g 柔性电路每 2 秒采样并通过 BLE 传输。作者先用人工溶液和台式电化学工作站校准，再在大麦上做钾、盐和光照实验，并在黄瓜、番茄上验证多日佩戴。</p></div></section>\n                </div>\n                <section class=\"review-contributions\"><div class=\"review-title\"><b>03</b><h4>主要贡献</h4><span>作者实际交付了什么</span></div><ol><li><span>01</span><p>建立不穿刺叶片的吐水液连续采集机制，把间歇微液滴转成可刷新的传感界面。</p></li><li><span>02</span><p>把三种生化指标、温湿度补偿、柔性读出和无线传输整合为完整的叶上系统。</p></li><li><span>03</span><p>在多日实验中观察到根部离子处理和光照变化对应的动态生化响应，并验证七天贴附对叶片形态和光合作用影响有限。</p></li></ol></section>\n                <section class=\"review-delta\"><div class=\"review-title\"><b>04</b><h4>相较以往的 delta</h4><span>过去做法 → 本文改变 → 仍需付出的代价</span></div><p>以往植物可穿戴多测温湿度、应变、挥发物或需要刺入组织；本文借用人体汗液 sensing 的系统思路，利用植物自己排出的液体做无创、连续、多指标化学监测。代价是只有会稳定吐水、且根压高和蒸腾低时才能工作。</p></section>\n                <div class=\"review-pair judgement\">\n                  <section class=\"review-block evidence\"><b>05</b><div><h4>证据够不够</h4><p>从微流体仿真、台式仪器对照、干扰测试、12 小时漂移，到三种植物的多日实验形成了较完整的系统验证链；大麦的重复测量统计显示处理效应。但关键压力实验多为每组约 5 株、环境受控，离真实田间规模仍远。</p></div></section>\n                  <section class=\"review-block limitations\"><b>06</b><div><h4>局限与不可外推之处</h4><p>依赖吐水现象，在低根压、高蒸腾或干燥环境中可能没有样本；目前只有钾、钠和葡萄糖三类指标；实验主要在室内受控条件和少量植株上完成，设备耐候性、长期校准、规模化网络和田间维护尚未验证。</p></div></section>\n                </div>\n                <div class=\"review-bottom\">\n                  <section><span>WHY READ</span><h4>为什么值得你读</h4><p>这是很好的科研视野扩展：同一套 wearable/microfluidic/sensing 设计语言可以从人体迁移到植物，并暴露出完全不同的采样可用性约束。</p></section>\n                  <section><span>READING PATH</span><h4>如果打开原文，优先看这里</h4><p>看 Fig. 1 的整体架构、Fig. 4 的无线系统验证、Fig. 5 的多日胁迫实验，以及 Discussion 对“只有产生吐水液时才适用”的限制。</p></section>\n                </div>\n              </div>\n            </details>\n            <div class=\"paper-links\"><a href=\"https://doi.org/10.1038/s41467-026-77955-6\" target=\"_blank\" rel=\"noreferrer\">论文页面 ↗</a><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC13720148/\" target=\"_blank\" rel=\"noreferrer\">阅读全文 ↗</a></div>\n          </div>\n          <aside class=\"why\"><span>SERENDIPITY</span><p>这是很好的科研视野扩展：同一套 wearable/microfluidic/sensing 设计语言可以从人体迁移到植物，并暴露出完全不同的采样可用性约束。</p></aside>\n        </article></section></main>\n<footer><div><span class=\"brand-mark\">RD</span><p><strong>Research Daily</strong><br>读全文，讲人话，不重复。</p></div><p>6 PAPERS · 31 MINUTES<br>ARCHIVED · 2026-11-10</p><a href=\"#top\">BACK TO TOP ↑</a></footer><script src=\"../../app.js\"></script><script src=\"../../feedback.js\"></script></body></html>"},"/archive/index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Research Daily · 综合目录</title><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link href=\"https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Noto+Sans+SC:wght@400;500;600;700;900&family=Noto+Serif+SC:wght@600;700;900&display=swap\" rel=\"stylesheet\"><link rel=\"stylesheet\" href=\"../styles.css\"></head><body><header class=\"masthead\"><a class=\"brand\" href=\"./\"><span class=\"brand-mark\">RD</span><span><strong>RESEARCH DAILY</strong><small>FULL-TEXT REVIEWED</small></span></a><div class=\"issue\">PERMANENT ARCHIVE</div></header><main class=\"archive-home\"><p class=\"eyebrow\">EVERY EDITION, KEPT</p><h1>综合<br><em>早报目录</em></h1><p class=\"dek\">每天的报告都按日期独立保存。旧内容不会被新一期覆盖，已经推荐过的论文也不会重新占用每日名额。</p><div class=\"archive-grid\"><a class=\"archive-card\" href=\"./2026-11-10/\"><span>2026-11-10</span><strong>6 篇论文</strong><b>31 min</b><i>打开本期 →</i></a></div></main><footer><div><span class=\"brand-mark\">RD</span><p><strong>Research Daily</strong><br>读全文，讲人话，不重复。</p></div><p>1 ARCHIVED EDITION</p><a href=\"./\">返回目录顶部 ↑</a></footer></body></html>"},"/feedback.js":{"type":"text/javascript; charset=utf-8","body":"const FEEDBACK_SIGNALS = [\n  ['interested', '★ 更关注'],\n  ['more', '＋ 多来这类'],\n  ['less', '− 少来这类'],\n  ['question', '? 有问题'],\n];\n\nfunction feedbackPaperId(article) {\n  const reviewId = article.querySelector('details[data-review]')?.dataset.review;\n  if (reviewId) return reviewId;\n  return article.id?.startsWith('paper-') ? article.id.slice(6) : '';\n}\n\nfunction feedbackBriefDate() {\n  const archived = location.pathname.match(/\\/archive\\/(\\d{4}-\\d{2}-\\d{2})\\//);\n  return archived?.[1] || document.querySelector('.issue')?.textContent.match(/\\d{4}-\\d{2}-\\d{2}/)?.[0] || '2026-11-10';\n}\n\ndocument.querySelectorAll('article.paper').forEach((article) => {\n  const main = article.querySelector('.paper-main');\n  const paperId = feedbackPaperId(article);\n  const title = article.querySelector('h3')?.textContent?.trim() || '';\n  if (!main || !paperId || main.querySelector('.feedback-panel')) return;\n\n  const panel = document.createElement('section');\n  panel.className = 'feedback-panel';\n  panel.dataset.paperId = paperId;\n  panel.innerHTML = `\n    <div class=\"feedback-heading\">\n      <div><span>YOUR SIGNAL</span><h4>这篇文章给你的反馈</h4></div>\n      <p>只保存你主动提交的内容，用于调整后续选题与精读重点。</p>\n    </div>\n    <div class=\"feedback-signals\" role=\"group\" aria-label=\"反馈类型\">\n      ${FEEDBACK_SIGNALS.map(([value, label]) => `<button type=\"button\" data-signal=\"${value}\">${label}</button>`).join('')}\n    </div>\n    <label class=\"feedback-note\">\n      <span>你真正关注的问题</span>\n      <textarea rows=\"3\" maxlength=\"4000\" placeholder=\"例如：我更关心它如何处理跨用户泛化；也可以粘贴你在 Gemini 中针对这篇论文提出的问题片段。\"></textarea>\n    </label>\n    <div class=\"feedback-actions\">\n      <label><span>内容来源</span><select><option value=\"site\">网页反馈</option><option value=\"gemini\">Gemini 提问片段</option><option value=\"other\">其他笔记</option></select></label>\n      <button class=\"feedback-submit\" type=\"button\">保存反馈 →</button>\n      <p class=\"feedback-status\" role=\"status\" aria-live=\"polite\"></p>\n    </div>`;\n  main.append(panel);\n\n  let selectedSignal = 'interested';\n  const buttons = panel.querySelectorAll('[data-signal]');\n  buttons[0].classList.add('selected');\n  buttons.forEach((button) => button.addEventListener('click', () => {\n    buttons.forEach((candidate) => candidate.classList.remove('selected'));\n    button.classList.add('selected');\n    selectedSignal = button.dataset.signal;\n  }));\n\n  panel.querySelector('.feedback-submit').addEventListener('click', async () => {\n    const submit = panel.querySelector('.feedback-submit');\n    const status = panel.querySelector('.feedback-status');\n    const note = panel.querySelector('textarea').value.trim();\n    const source = panel.querySelector('select').value;\n    if ((selectedSignal === 'question' || source === 'gemini') && !note) {\n      status.textContent = '请先写下问题或粘贴提问片段。';\n      return;\n    }\n    submit.disabled = true;\n    status.textContent = '正在保存…';\n    try {\n      const response = await fetch('/api/feedback', {\n        method: 'POST',\n        headers: {'content-type': 'application/json'},\n        body: JSON.stringify({paperId, title, briefDate: feedbackBriefDate(), signal: selectedSignal, note, source}),\n      });\n      const payload = await response.json();\n      if (!response.ok) throw new Error(payload.error || '保存失败');\n      panel.querySelector('textarea').value = '';\n      status.textContent = '已保存。下一期选题会读取这条信号。';\n    } catch (error) {\n      status.textContent = `未保存：${error.message}`;\n    } finally {\n      submit.disabled = false;\n    }\n  });\n});\n"},"/index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n  <meta name=\"description\" content=\"面向 HCI、UbiComp、Sensing、Health AI 与 Robotics 的全文精读学术早报\" />\n  <title>Research Daily · 2026.11.10</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Noto+Sans+SC:wght@400;500;600;700;900&family=Noto+Serif+SC:wght@600;700;900&display=swap\" rel=\"stylesheet\">\n  <link rel=\"stylesheet\" href=\"./styles.css\" />\n</head>\n<body>\n  <header class=\"masthead\">\n    <a class=\"brand\" href=\"./archive/\" aria-label=\"前往综合目录\">\n      <span class=\"brand-mark\">RD</span>\n      <span><strong>RESEARCH DAILY</strong><small>FULL-TEXT REVIEWED</small></span>\n    </a>\n    <div class=\"issue\"><a class=\"archive-link\" href=\"./archive/\">历史归档</a>&nbsp;&nbsp;·&nbsp;&nbsp;ISSUE 001&nbsp;&nbsp;·&nbsp;&nbsp;10 NOV 2026</div>\n  </header>\n\n  <main id=\"top\">\n    <section class=\"hero\">\n      <div class=\"hero-copy\">\n        <p class=\"eyebrow\">YOUR 30-MINUTE RESEARCH WINDOW</p>\n        <h1>今天值得读的<br><em>六篇论文</em></h1>\n        <p class=\"dek\">从个人可穿戴数据的 AI agent，到消费手表筛查高血压。所有论文均已阅读全文；这里留下的是结论、证据与真正的增量。</p>\n        <div class=\"hero-actions\">\n          <a class=\"primary\" href=\"#start\">开始阅读 <span>↓</span></a>\n          <button class=\"ghost\" id=\"focusToggle\" type=\"button\">开启专注模式</button>\n        </div>\n      </div>\n      <aside class=\"reading-map\" aria-label=\"今日阅读分布\">\n        <div class=\"map-head\"><span>READING MAP</span><strong>31<span>MIN</span></strong></div>\n        <div class=\"timeline\" aria-hidden=\"true\">\n          <span class=\"t-core\" style=\"width:48.4%\"></span>\n          <span class=\"t-adjacent\" style=\"width:16.1%\"></span>\n          <span class=\"t-landmark\" style=\"width:19.4%\"></span>\n          <span class=\"t-random\" style=\"width:16.1%\"></span>\n        </div>\n        <ol>\n          <li><i class=\"core-dot\"></i><span>主要相关</span><b>3 篇 · 15 min</b></li>\n          <li><i class=\"adjacent-dot\"></i><span>次要相关</span><b>1 篇 · 5 min</b></li>\n          <li><i class=\"landmark-dot\"></i><span>重要文献</span><b>1 篇 · 6 min</b></li>\n          <li><i class=\"random-dot\"></i><span>随机看一篇</span><b>1 篇 · 5 min</b></li>\n        </ol>\n        <p>引用数据查询于 2026-11-10</p>\n      </aside>\n    </section>\n\n    <section class=\"priority\" id=\"start\">\n      <div class=\"priority-label\"><span>IF YOU ONLY READ TWO</span><b>只读两篇</b></div>\n      <a href=\"#phia\"><span>01</span><strong>让 AI 真正“算”你的可穿戴数据，而不是凭感觉回答</strong><i>6 min ↗</i></a>\n      <a href=\"#hypertension\"><span>02</span><strong>手表不报血压数字，反而更可能抓住长期高血压</strong><i>6 min ↗</i></a>\n    </section>\n\n    <nav class=\"section-nav\" aria-label=\"文章板块\">\n      <a href=\"#core\"><span>01</span>主要相关</a>\n      <a href=\"#adjacent\"><span>02</span>次要相关</a>\n      <a href=\"#landmark\"><span>03</span>重要文献</a>\n      <a href=\"#random\"><span>04</span>随机看一篇</a>\n    </nav>\n\n    <section class=\"paper-section core\" id=\"core\">\n      <header class=\"section-head\">\n        <div><span class=\"section-no\">01</span><p>PRIMARY SIGNAL</p></div>\n        <h2>主要相关</h2>\n        <p>与你的 HCI / UbiComp / sensing 研究直接相连。优先看方法设计、测量有效性和可复用的系统思路。</p>\n      </header>\n\n      <article class=\"paper featured\" id=\"phia\">\n        <div class=\"paper-index\">01</div>\n        <div class=\"paper-main\">\n          <div class=\"meta\"><span>Nature Communications · 2026</span><span>6 MIN</span><span>78 CITATIONS</span></div>\n          <h3>Transforming wearable data into personal health insights using large language model agents</h3>\n          <p class=\"authors\">Mike A. Merrill, Akshay Paruchuri, Naghmeh Rezaei et al.</p>\n          <div class=\"plain\"><small>说人话</small><p>让语言模型先拆问题、写代码算个人可穿戴数据、出错后再重试，比一次性给答案可靠得多；但这篇论文证明的是“答题能力”，不是这些建议真的能改善健康。</p></div>\n          <div class=\"metrics\"><div><strong>84%</strong><span>客观问题准确率</span></div><div><strong>0.192</strong><span>代码错误率</span></div><div><strong>4,000+</strong><span>评测问题</span></div></div>\n          <details data-review=\"p_1e363db76b43e7ce\"><summary>展开完整精读笔记 <span>+</span></summary><div class=\"review-loading\">正在载入精读笔记…</div></details>\n          <div class=\"paper-links\"><a href=\"https://doi.org/10.1038/s41467-025-67922-y\" target=\"_blank\" rel=\"noreferrer\">论文页面 ↗</a><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC12855967/\" target=\"_blank\" rel=\"noreferrer\">阅读全文 ↗</a></div>\n        </div>\n        <aside class=\"why\"><span>WHY IT MATTERS</span><p>它把连续传感数据从“模型输入”变成可追问、可计算、可审计的交互对象。</p></aside>\n      </article>\n\n      <article class=\"paper\">\n        <div class=\"paper-index\">02</div><div class=\"paper-main\">\n          <div class=\"meta\"><span>Nature Communications · 2026</span><span>5 MIN</span><span>0 CITATIONS</span></div>\n          <h3>Silicon-photonics optoacoustic sensor for fully wearable blood pressure monitoring</h3>\n          <p class=\"authors\">Gil Gelbert, Ron Moisseev, Yoav Hazan et al.</p>\n          <div class=\"plain\"><small>说人话</small><p>作者把需要多阵元、精确对准血管的超声方案，换成一个极小的光声探头；重新贴到手腕仍能跟踪血压波形，但人体实验目前只有两个人。</p></div>\n          <details data-review=\"p_f5e81a6a7e372cdc\"><summary>展开完整精读笔记 <span>+</span></summary><div class=\"review-loading\">正在载入精读笔记…</div></details>\n          <div class=\"paper-links\"><a href=\"https://doi.org/10.1038/s41467-026-77580-3\" target=\"_blank\" rel=\"noreferrer\">论文页面 ↗</a><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC13680363/\" target=\"_blank\" rel=\"noreferrer\">阅读全文 ↗</a></div>\n        </div><aside class=\"why\"><span>WATCH OUT</span><p><strong>n = 2</strong><br>工程创新很强，临床证据仍是早期原型级。</p></aside>\n      </article>\n\n      <article class=\"paper\">\n        <div class=\"paper-index\">03</div><div class=\"paper-main\">\n          <div class=\"meta\"><span>npj Biological Timing and Sleep · 2026</span><span>4 MIN</span><span>0 CITATIONS</span></div>\n          <h3>Five wearable sensors for objective measurement of near work and light exposure</h3>\n          <p class=\"authors\">Raman Prasad Sah, Nebee Yohannes, Pavan Narra, Lisa A. Ostrin</p>\n          <div class=\"plain\"><small>说人话</small><p>同一个人、同一天戴着五种设备，测出来的“近距离用眼时间”和室内光照仍会不一样；研究者选哪种传感器，会直接改变最后得到的行为结论。</p></div>\n          <details data-review=\"p_1a21c67395ea6e02\"><summary>展开完整精读笔记 <span>+</span></summary><div class=\"review-loading\">正在载入精读笔记…</div></details>\n          <div class=\"paper-links\"><a href=\"https://doi.org/10.1038/s44323-026-00113-0\" target=\"_blank\" rel=\"noreferrer\">论文页面 ↗</a><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC13739900/\" target=\"_blank\" rel=\"noreferrer\">阅读全文 ↗</a></div>\n        </div><aside class=\"why\"><span>METHOD NOTE</span><p>传感器位置、阈值与采样策略不是实现细节，它们会改变科学结论。</p></aside>\n      </article>\n    </section>\n\n    <section class=\"paper-section adjacent\" id=\"adjacent\">\n      <header class=\"section-head\"><div><span class=\"section-no\">02</span><p>ADJACENT FIELD</p></div><h2>次要相关</h2><p>不在主航道上，但其评估方法和部署教训能直接迁移到 HCI、HRI 与 sensing。</p></header>\n      <article class=\"paper\">\n        <div class=\"paper-index\">04</div><div class=\"paper-main\">\n          <div class=\"meta\"><span>Frontiers in Robotics and AI · 2026</span><span>5 MIN</span><span>0 CITATIONS</span></div>\n          <h3>QAMQOR: a benchmark dataset for engagement recognition in robot-assisted autism therapy</h3>\n          <p class=\"authors\">Nazerke Rakhymbayeva, Aida Tungatarova, Zhansaule Telisheva, Anara Sandygulova</p>\n          <div class=\"plain\"><small>说人话</small><p>最重要的发现不是某个模型更强，而是把同一个孩子或同一场治疗的视频同时放进训练集和测试集，会让结果看起来好得不真实。</p></div>\n          <div class=\"metrics\"><div><strong>47 h</strong><span>真实治疗视频</span></div><div><strong>34</strong><span>名儿童</span></div><div><strong>0.12</strong><span>切分造成的 F1 变化</span></div></div>\n          <details data-review=\"p_4bee27f7d05ad6b3\"><summary>展开完整精读笔记 <span>+</span></summary><div class=\"review-loading\">正在载入精读笔记…</div></details>\n          <div class=\"paper-links\"><a href=\"https://doi.org/10.3389/frobt.2026.1868211\" target=\"_blank\" rel=\"noreferrer\">论文页面 ↗</a><a href=\"https://www.frontiersin.org/journals/robotics-and-ai/articles/10.3389/frobt.2026.1868211/full\" target=\"_blank\" rel=\"noreferrer\">阅读全文 ↗</a></div>\n        </div><aside class=\"why\"><span>TRANSFERABLE IDEA</span><p>评估协议造成的差异，可能比模型结构造成的差异还大。</p></aside>\n      </article>\n    </section>\n\n    <section class=\"paper-section landmark\" id=\"landmark\">\n      <header class=\"section-head\"><div><span class=\"section-no\">03</span><p>LANDMARK READ</p></div><h2>重要文献</h2><p>值得被更多人讨论的工作：不仅有新方法，也重新定义了传感器应该解决的问题。</p></header>\n      <article class=\"paper featured\" id=\"hypertension\">\n        <div class=\"paper-index\">05</div><div class=\"paper-main\">\n          <div class=\"meta\"><span>Nature · 2026</span><span>6 MIN</span><span>1 CITATION</span></div>\n          <h3>Opportunistically Detecting Signs of Hypertension on a Consumer Smartwatch</h3>\n          <p class=\"authors\">Paolo Di Achille, Lawrence Cai, Jiang Wu et al.</p>\n          <div class=\"plain\"><small>说人话</small><p>这块手表不尝试报出你此刻的血压，而是连续看一周的脉搏光学信号和动作，判断你是否可能长期偏高；它比一次门诊测量多抓到一些人，但仍漏掉约三分之一病例。</p></div>\n          <div class=\"metrics\"><div><strong>65.8%</strong><span>灵敏度</span></div><div><strong>90.0%</strong><span>特异度</span></div><div><strong>196</strong><span>完整分析样本</span></div></div>\n          <details data-review=\"p_e1401bb657deafba\"><summary>展开完整精读笔记 <span>+</span></summary><div class=\"review-loading\">正在载入精读笔记…</div></details>\n          <p class=\"access-note\">全文阅读使用公开 medRxiv 完整稿，并与 Nature 同行评审版本的题录和主要结果交叉核对。</p>\n          <div class=\"paper-links\"><a href=\"https://doi.org/10.1038/s41586-026-11336-3\" target=\"_blank\" rel=\"noreferrer\">Nature 页面 ↗</a><a href=\"https://www.medrxiv.org/content/10.64898/2025.12.10.25341972v1.full\" target=\"_blank\" rel=\"noreferrer\">完整稿 ↗</a></div>\n        </div><aside class=\"why\"><span>KEY REFRAME</span><p>与其硬做不稳定的连续回归，不如重新定义临床上真正有价值的筛查任务。</p></aside>\n      </article>\n    </section>\n\n    <section class=\"paper-section random\" id=\"random\">\n      <header class=\"section-head\"><div><span class=\"section-no\">04</span><p>SERENDIPITY</p></div><h2>随机看一篇</h2><p>离开熟悉领域五分钟。寻找可迁移的方法、意外的约束，以及新的研究语言。</p></header>\n      <article class=\"paper\">\n        <div class=\"paper-index\">06</div><div class=\"paper-main\">\n          <div class=\"meta\"><span>Nature Communications · 2026</span><span>5 MIN</span><span>0 CITATIONS</span></div>\n          <h3>A multiplexed wearable microfluidic platform for non-invasive sweat-inspired monitoring of plant guttation biomarkers</h3>\n          <p class=\"authors\">Bing Xue, Ziyang Huang, Zhiyuan Li et al.</p>\n          <div class=\"plain\"><small>说人话</small><p>作者把人类汗液贴片的思路搬到了叶子上：设备接住植物自然渗出的微小液滴，连续测钾、钠和葡萄糖，让植物的盐胁迫和光照反应可以被实时看见。</p></div>\n          <details data-review=\"p_a2b9a04907675c47\"><summary>展开完整精读笔记 <span>+</span></summary><div class=\"review-loading\">正在载入精读笔记…</div></details>\n          <div class=\"paper-links\"><a href=\"https://doi.org/10.1038/s41467-026-77955-6\" target=\"_blank\" rel=\"noreferrer\">论文页面 ↗</a><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC13720148/\" target=\"_blank\" rel=\"noreferrer\">阅读全文 ↗</a></div>\n        </div><aside class=\"why\"><span>WHY RANDOM?</span><p>同一套 wearable / microfluidic 设计语言，迁移到植物后会暴露完全不同的采样约束。</p></aside>\n      </article>\n    </section>\n  </main>\n\n  <footer><div><span class=\"brand-mark\">RD</span><p><strong>Research Daily</strong><br>读全文，讲人话，不重复。</p></div><p>6 PAPERS · 31 MINUTES<br>FULL-TEXT VERIFIED · 10 NOV 2026</p><a href=\"#top\">BACK TO TOP ↑</a></footer>\n  <script src=\"./review-data.js\"></script>\n  <script src=\"./app.js\"></script>\n  <script src=\"./feedback.js\"></script>\n</body>\n</html>\n"},"/review-data.js":{"type":"text/javascript; charset=utf-8","body":"window.RESEARCH_REVIEWS = {\n  \"p_1e363db76b43e7ce\": {\n    problem: \"像“运动后的睡眠是否更好”这类个人健康问题既需要准确计算时间序列，又需要结合背景知识。纯文本推理容易算错，单次代码生成也无法发现并修复自己的错误。\",\n    method: \"PHIA 把规划、Python 数据分析和网页检索组合成多步 agent。作者构建了 4000 多个封闭式和开放式问题，用来源于 3 万名同意参与研究的 Fitbit / Pixel Watch 用户数据训练生成器并合成 56 个虚拟用户，抽取 4 个做客观评估；开放问题由多人盲评，累计约 650 小时人工评估。\",\n    contributions: [\n      \"提出一个针对个人可穿戴时间序列的 agent 工作流，可反复生成代码、检查结果、检索背景知识并修正错误。\",\n      \"发布高保真合成可穿戴数据和 4000 多题的个人健康洞察评测集，降低真实个人数据的隐私风险。\",\n      \"在客观问题上达到 84% 准确率；代码错误率为 0.192，而单次代码生成基线为 0.395，并展示了非零的自我恢复能力。\"\n    ],\n    delta: \"以往工作多把汇总后的可穿戴指标直接塞进模型，或让模型一次生成代码；PHIA 把问题分解、代码执行、外部检索和迭代纠错串成闭环。真正的增量是可执行且能恢复的分析流程，而不是单纯换了更大的语言模型。\",\n    evidence: \"同一底层模型下与数值推理、代码生成等基线比较，能较好隔离 agent 流程本身的作用；人工盲评规模也很大。可是客观评估主要依赖 4 个合成用户，开放问题由熟悉消费健康数据但不是临床医生的评审评价，且没有真实用户健康结局。\",\n    limitations: \"没有证明用户会更理解数据、改变行为或获得临床收益；医学建议的真实性没有由临床专家系统评估；问题来源部分来自作者同事，可能不代表普通用户；合成数据虽保护隐私，但可能弱化真实世界的长尾缺失、设备故障和复杂共病。\",\n    whyRead: \"它正好连接 sensing、personal informatics 和 AI agent：展示了如何把连续传感数据从“模型输入”变成可追问、可计算、可审计的交互式分析对象。\",\n    readingPath: \"先看 Fig. 7 的 agent 流程，再看 Fig. 1–4 的错误率与恢复率；最后精读 Discussion 的四项限制和 Synthetic wearable user data 方法。\"\n  },\n  \"p_f5e81a6a7e372cdc\": {\n    problem: \"连续无袖带血压监测需要直接、稳定地测量动脉变化。现有 PPG 多为间接估计且容易受位置和个体差异影响，超声贴片虽然更直接，却依赖阵列和精确对准小动脉。\",\n    method: \"系统用硅光子声学探测器 SPADE 接收光激发动脉产生的光声信号，从信号时延估计桡动脉内径。作者先用仿体和多角度、位移实验验证位置鲁棒性，再在一男一女两名志愿者上进行 3 个月、120 段各 10 秒的测量，与 Finapres 袖带 / 指套参考系统比较；每人只在最初校准一次。\",\n    contributions: [\n      \"用单个微型、近全向的硅光子探测元件替代密集超声阵列，直接读取动脉内腔边界。\",\n      \"在平移、旋转和反复移除重贴条件下展示较低的直径估计波动，说明方案对佩戴位置更宽容。\",\n      \"在两名被试的 120 次测量中得到舒张压 2.6 mmHg、收缩压 4.7 mmHg 的平均绝对差。\"\n    ],\n    delta: \"以往可穿戴超声依靠聚焦或多阵元找准血管，复杂度和位置敏感性随血管变小而增加；本文利用血液相对周围组织更强的光声对比度，加上微型近全向探测器，用单元件完成测量。代价是当前仍需要桌面激光器、耦合胶和个体初始校准。\",\n    evidence: \"仿体、与压电探头的对照以及跨三个月重复贴附共同支持“位置鲁棒”这一工程主张；血压误差也有同步参考设备。不过临床数据只有两人，120 个短片段并不等于 120 个独立受试者，不能据此宣称达到普遍临床可用性。\",\n    limitations: \"人体样本 n=2，主要在静坐和短暂核心发力状态下测试；每人仍需一次校准；参考系统本身有误差；装置尚包含体积较大的激光和光学读出，离真正日常佩戴还有明显工程距离。作者也明确承认需要超过 85 人的标准化临床验证。\",\n    whyRead: \"这是很典型的 sensing 系统论文：创新不是换一个分类器，而是利用新的物理对比机制改变对准、阵列规模和可穿戴化之间的设计空间。\",\n    readingPath: \"重点看 Fig. 5 的旋转对照、Fig. 6 的血压验证，以及 Discussion 第 247–271 段对位置鲁棒性、n=2 和桌面激光器的坦诚讨论。\"\n  },\n  \"p_1a21c67395ea6e02\": {\n    problem: \"近视研究越来越依赖可穿戴设备估计近距离用眼和光照，但不同佩戴位置、量程和采样方式的数据能否互相替代并不清楚，自我活动日志也可能系统性偏差。\",\n    method: \"30 名成年人在自然生活中连续约 14 小时同时佩戴两种眼镜式距离 / 光照传感器和三种腕式光照传感器，并填写活动日志。作者把距离和照度分箱，用配对的非参数统计比较设备间及设备与日志的一致性。\",\n    contributions: [\n      \"在完全相同的被试和时间段内直接比较五种常用设备，避免跨研究、跨样本比较造成的混淆。\",\n      \"发现五种设备对强户外光照的判断较一致，但眼镜式设备对近距离和中距离用眼给出显著不同的时长分布。\",\n      \"证明活动日志会低估近距离用眼、并高估中距离用眼和部分户外时长，说明主观记录不能简单代替客观测量。\"\n    ],\n    delta: \"过去很多研究使用单一设备或自我日志，默认这些测量大致等价；本文让五种设备被同时佩戴，直接量化了设备选择带来的系统差异。增量不是新传感器，而是把“测量工具本身”当成需要验证的研究变量。\",\n    evidence: \"同一被试同步佩戴使比较很干净，统计检验也报告了校正后的显著性和效应量。强户外光照的一致性结论可信；但由于没有真实观看距离和眼部照度的金标准，结果只能说明相互一致或不一致，不能判断哪台设备绝对更准。\",\n    limitations: \"样本只有 30 名健康成年人、仅记录一天且都在休斯敦；没有实验室金标准；手腕遮挡、眼镜安装角度和各设备采样周期不同。部分设备由厂商提供，通讯作者披露了与 Meta、Zeiss 和相关专利的关系。\",\n    whyRead: \"它对 sensing 研究很实用：提醒我们在真实部署中，传感器位置、阈值和采样策略不是实现细节，而会改变行为标签与科学结论。\",\n    readingPath: \"先看图 4–6 的同步轨迹和分箱结果，再看 Table 5 的设备规格，最后读 Discussion 中关于无金标准和设备差异的解释。\"\n  },\n  \"p_4bee27f7d05ad6b3\": {\n    problem: \"机器人辅助孤独症治疗需要识别儿童是否投入互动，但公开数据少、样本小，很多论文随机切视频帧，导致同一儿童或同一会话泄漏到训练和测试两边。\",\n    method: \"QAMQOR 收集了 34 名 3–12 岁孤独症儿童与 NAO 机器人进行治疗活动的 187 个会话、约 47 小时视频，并提取脸、身体和手部姿态特征。作者定义随机、儿童独立、会话独立和活动独立四种划分，统一比较逻辑回归、树模型、时序 XGBoost、LSTM 和 TCN，并单独测试类别平衡。\",\n    contributions: [\n      \"公开一个真实治疗环境中的参与度数据集，并随数据给出防泄漏的标准化划分。\",\n      \"量化评估协议的影响：多分类任务中，不同划分造成的 macro-F1 变化约 0.12，而可学习分类器之间只有约 0.07。\",\n      \"显示儿童独立划分接近机会水平，且在同等、未调参条件下，LSTM / TCN 没有优于简单树模型。\"\n    ],\n    delta: \"过去数据集往往只提供数据，论文各自随机划分并报告一个漂亮数字；QAMQOR 把“能否泛化到新儿童、新会话和新活动”写进基准协议。增量是把部署条件固化为评估制度，而不是再发明一个网络。\",\n    evidence: \"34 名儿童、187 个真实会话比常见小型 HRI 实验更贴近部署，四种划分和多类模型能直接展示泄漏效应。结果也诚实地暴露了模型几乎不可用的儿童独立表现。但深度模型未专门调参，所以不能得出“深度学习无用”的一般结论。\",\n    limitations: \"独立参与者仍只有 34 人，性别极不均衡（32 男、2 女），姿态按 1 fps 采样且主要使用视频关键点；行为和年龄异质性大，模型没有做个体校准；当前性能不足以让机器人对陌生儿童自动调整治疗。\",\n    whyRead: \"它是 HRI / sensing 评估设计的好例子：研究贡献可以是揭示数据切分比模型结构更重要，并把生态有效性写入 benchmark。\",\n    readingPath: \"看 Table 2 的队列结构、四种 evaluation protocols、Fig. 5 与 Sections 5.2 / 5.6 的模型比较，以及 Discussion 6.1 对实际部署的解释。\"\n  },\n  \"p_e1401bb657deafba\": {\n    problem: \"高血压筛查依赖袖带，单次门诊测量会受白大衣效应影响，也会漏掉隐匿性高血压。过去无袖带方案常估计瞬时血压，受动作、接触压力和个体差异影响，并且常用家庭血压而非 24 小时动态血压作标签。\",\n    method: \"研究把 Pixel Watch 3 的 PPG 与加速度波形编码成个体表示，再用身高和逻辑回归判断高血压状态。前瞻性多中心队列在 5 个美国站点招募 296 人，196 人有完整门诊和 24 小时动态血压数据并进入分析；参与者在自由生活中佩戴手表约 7 天，并与动态血压、家庭血压和门诊血压逐一比较。\",\n    contributions: [\n      \"把目标从估计某一时刻的收缩压 / 舒张压，改成从多日传感数据识别持续性高血压状态。\",\n      \"同时利用 PPG 和加速度波形，而不只是用加速度筛选静止片段，也不要求先用袖带为个人校准。\",\n      \"以 24 小时动态血压为金标准，得到 65.8% 灵敏度、90.0% 特异度和 80.6% 阳性预测值；单次门诊筛查对应为 55.3%、90.0% 和 77.8%。\"\n    ],\n    delta: \"此前无袖带研究多追求逐点血压数值，容易被波形噪声和校准拖累；本文退一步做长期状态筛查，并用自由生活的一周信号和动态血压真值验证。这个重构让消费手表更可能成为筛查入口，但它不是血压计，也不能完成诊断。\",\n    evidence: \"前瞻、多中心、自由生活、与同一批人的 24 小时动态血压头对头比较，是很强的临床转化设计；肤色分布也较多样。另一方面，只有 196 / 296 人进入最终分析，缺失主要来自动态血压；灵敏度置信区间较宽，且 65.8% 本身说明漏诊仍多。\",\n    limitations: \"排除了已知心血管病和正在服降压药的人，不能外推到治疗人群；只测试一种手表和美国站点；34% 招募者因数据不完整未进入主要分析；模型输出是风险提示而非诊断，尚未证明提示能改善就医、血压控制或心血管结局。\",\n    whyRead: \"这是一篇 sensing 目标函数设计的代表作：与其硬做不稳定的连续回归，不如重新定义临床上真正有价值、且传感器能可靠承担的筛查任务。\",\n    readingPath: \"优先看 prospective validation study、Fig. 1 的流程、与门诊 / 家庭血压的头对头结果、error analysis，以及 Discussion 中对缺失数据和适用人群的限制。\"\n  },\n  \"p_a2b9a04907675c47\": {\n    problem: \"植物内部液体能反映营养和胁迫，但传统方法需要穿刺或间歇取样；叶缘自然分泌的吐水液虽无创，却体积小、出现不连续且很快蒸发。\",\n    method: \"PlantIonics 用仿猪笼草表面的楔形亲 / 疏水微流道，在约 0.6 秒内把吐水液单向送到钾、钠、葡萄糖电化学传感阵列；0.16 g 柔性电路每 2 秒采样并通过 BLE 传输。作者先用人工溶液和台式电化学工作站校准，再在大麦上做钾、盐和光照实验，并在黄瓜、番茄上验证多日佩戴。\",\n    contributions: [\n      \"建立不穿刺叶片的吐水液连续采集机制，把间歇微液滴转成可刷新的传感界面。\",\n      \"把三种生化指标、温湿度补偿、柔性读出和无线传输整合为完整的叶上系统。\",\n      \"在多日实验中观察到根部离子处理和光照变化对应的动态生化响应，并验证七天贴附对叶片形态和光合作用影响有限。\"\n    ],\n    delta: \"以往植物可穿戴多测温湿度、应变、挥发物或需要刺入组织；本文借用人体汗液 sensing 的系统思路，利用植物自己排出的液体做无创、连续、多指标化学监测。代价是只有会稳定吐水、且根压高和蒸腾低时才能工作。\",\n    evidence: \"从微流体仿真、台式仪器对照、干扰测试、12 小时漂移，到三种植物的多日实验形成了较完整的系统验证链；大麦的重复测量统计显示处理效应。但关键压力实验多为每组约 5 株、环境受控，离真实田间规模仍远。\",\n    limitations: \"依赖吐水现象，在低根压、高蒸腾或干燥环境中可能没有样本；目前只有钾、钠和葡萄糖三类指标；实验主要在室内受控条件和少量植株上完成，设备耐候性、长期校准、规模化网络和田间维护尚未验证。\",\n    whyRead: \"这是很好的科研视野扩展：同一套 wearable / microfluidic / sensing 设计语言可以从人体迁移到植物，并暴露出完全不同的采样可用性约束。\",\n    readingPath: \"看 Fig. 1 的整体架构、Fig. 4 的无线系统验证、Fig. 5 的多日胁迫实验，以及 Discussion 对“只有产生吐水液时才适用”的限制。\"\n  }\n};\n"},"/styles.css":{"type":"text/css; charset=utf-8","body":":root{--ink:#11110f;--paper:#f3f0e9;--line:#c9c4b8;--muted:#6f6b62;--core:#ff5a36;--adjacent:#2563eb;--landmark:#8d5cf6;--random:#22946f;--display:\"Noto Serif SC\",serif;--sans:\"Noto Sans SC\",sans-serif;--mono:\"DM Mono\",monospace}\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);font-size:16px}.masthead{height:82px;border-bottom:1px solid var(--ink);display:flex;align-items:center;justify-content:space-between;padding:0 clamp(24px,5vw,80px);position:relative;z-index:5}.brand{display:flex;align-items:center;gap:12px;color:inherit;text-decoration:none}.brand-mark{width:42px;height:42px;border-radius:50%;background:var(--ink);color:var(--paper);display:grid;place-items:center;font:500 14px var(--mono)}.brand strong,.brand small{display:block}.brand strong{font:700 15px var(--sans);letter-spacing:.08em}.brand small{font:400 9px var(--mono);letter-spacing:.15em;margin-top:3px}.issue{font:500 11px var(--mono);letter-spacing:.08em}.hero{min-height:610px;display:grid;grid-template-columns:minmax(0,1.3fr) minmax(320px,.7fr);gap:8vw;padding:80px clamp(24px,7vw,112px);align-items:center;border-bottom:1px solid var(--ink);background:radial-gradient(circle at 73% 18%,rgba(255,90,54,.16),transparent 26%),linear-gradient(115deg,#f7f3eb 0%,#ede8de 100%)}.eyebrow,.section-head p,.priority-label span{font:500 11px var(--mono);letter-spacing:.12em}.hero h1{font:900 clamp(54px,7.4vw,112px)/.98 var(--display);letter-spacing:-.065em;margin:18px 0 28px}.hero h1 em{color:var(--core);font-style:normal}.dek{font-size:clamp(16px,1.5vw,21px);line-height:1.8;max-width:720px;margin:0;color:#403e39}.hero-actions{display:flex;gap:12px;margin-top:38px}.primary,.ghost{height:48px;padding:0 22px;display:inline-flex;align-items:center;gap:34px;border:1px solid var(--ink);font:600 13px var(--sans);text-decoration:none;cursor:pointer}.primary{background:var(--ink);color:white}.ghost{background:transparent;color:var(--ink)}.reading-map{background:var(--ink);color:white;padding:28px;box-shadow:18px 18px 0 var(--core);transform:rotate(1deg)}.map-head{display:flex;align-items:flex-start;justify-content:space-between;font:500 10px var(--mono);letter-spacing:.1em}.map-head strong{font:500 64px/1 var(--mono);letter-spacing:-.08em}.map-head strong span{font-size:12px;margin-left:6px;letter-spacing:0}.timeline{display:flex;height:9px;margin:30px 0 18px}.timeline span{height:100%}.t-core{background:var(--core)}.t-adjacent{background:var(--adjacent)}.t-landmark{background:var(--landmark)}.t-random{background:var(--random)}.reading-map ol{list-style:none;padding:0;margin:0}.reading-map li{display:grid;grid-template-columns:12px 1fr auto;align-items:center;gap:10px;padding:13px 0;border-bottom:1px solid #3d3d39;font-size:13px}.reading-map li b{font:400 11px var(--mono);color:#aaa}.reading-map i{width:8px;height:8px;border-radius:50%}.core-dot{background:var(--core)}.adjacent-dot{background:var(--adjacent)}.landmark-dot{background:var(--landmark)}.random-dot{background:var(--random)}.reading-map>p{font:400 9px var(--mono);color:#777;margin:20px 0 0}.priority{display:grid;grid-template-columns:220px 1fr 1fr;border-bottom:1px solid var(--ink)}.priority>*{padding:28px 32px;border-right:1px solid var(--ink)}.priority>*:last-child{border-right:0}.priority-label{background:var(--core);color:white}.priority-label b,.priority-label span{display:block}.priority-label b{font:700 21px var(--display);margin-top:8px}.priority>a{color:inherit;text-decoration:none;display:grid;grid-template-columns:32px 1fr auto;gap:14px;align-items:start;transition:background .2s}.priority>a:hover{background:#fff}.priority>a span,.priority>a i{font:400 10px var(--mono);font-style:normal}.priority>a strong{font:700 16px/1.6 var(--sans)}.section-nav{height:64px;position:sticky;top:0;z-index:10;background:rgba(243,240,233,.94);backdrop-filter:blur(12px);display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid var(--ink)}.section-nav a{display:flex;justify-content:center;align-items:center;gap:10px;color:inherit;text-decoration:none;border-right:1px solid var(--line);font-size:13px}.section-nav a:last-child{border-right:0}.section-nav span{font:400 10px var(--mono);color:var(--muted)}.paper-section{--accent:var(--core);padding:0 clamp(24px,7vw,112px) 100px;scroll-margin-top:64px}.paper-section.adjacent{--accent:var(--adjacent)}.paper-section.landmark{--accent:var(--landmark)}.paper-section.random{--accent:var(--random)}.section-head{min-height:250px;display:grid;grid-template-columns:160px 1fr minmax(240px,420px);gap:40px;align-items:center;border-bottom:5px solid var(--accent)}.section-no{font:500 72px/1 var(--mono);color:var(--accent);letter-spacing:-.1em}.section-head div p{color:var(--accent)}.section-head h2{font:900 clamp(44px,5vw,74px)/1 var(--display);letter-spacing:-.05em;margin:0}.section-head>p{font:400 14px/1.8 var(--sans);letter-spacing:0;color:var(--muted)}.paper{display:grid;grid-template-columns:80px minmax(0,1fr) 240px;gap:36px;padding:54px 0;border-bottom:1px solid var(--ink);scroll-margin-top:84px}.paper-index{font:500 13px var(--mono);color:var(--accent);padding-top:5px}.meta{display:flex;flex-wrap:wrap;gap:9px;margin-bottom:16px}.meta span{font:500 10px var(--mono);padding:6px 8px;border:1px solid var(--line);background:rgba(255,255,255,.35)}.meta span:first-child{border-color:var(--accent);color:var(--accent)}.paper h3{font:800 clamp(25px,3vw,42px)/1.18 var(--display);letter-spacing:-.035em;margin:0;max-width:980px}.authors{font-size:12px;color:var(--muted);margin:14px 0 26px}.plain{display:grid;grid-template-columns:70px 1fr;gap:20px;border-left:5px solid var(--accent);padding:18px 22px;background:#fff}.plain small{font:600 10px var(--mono);color:var(--accent);padding-top:5px}.plain p{font:600 17px/1.75 var(--sans);margin:0}.metrics{display:grid;grid-template-columns:repeat(3,1fr);margin-top:16px;border:1px solid var(--line)}.metrics div{padding:18px;border-right:1px solid var(--line)}.metrics div:last-child{border:0}.metrics strong,.metrics span{display:block}.metrics strong{font:500 25px var(--mono);color:var(--accent)}.metrics span{font-size:10px;color:var(--muted);margin-top:5px}details{margin-top:18px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}summary{list-style:none;cursor:pointer;padding:17px 0;font:600 12px var(--sans);display:flex;justify-content:space-between}summary::-webkit-details-marker{display:none}summary span{font:400 18px var(--mono);transition:transform .2s}details[open] summary span{transform:rotate(45deg)}.details-grid{display:grid;grid-template-columns:1fr 1fr;gap:28px;padding:8px 0 24px}.details-grid h4{font:700 13px var(--sans);color:var(--accent);margin:0 0 8px}.details-grid p{font-size:13px;line-height:1.8;color:#45423c;margin:0}.paper-links{display:flex;gap:8px;margin-top:20px}.paper-links a{font:600 11px var(--sans);color:inherit;text-decoration:none;border:1px solid var(--ink);padding:9px 12px}.paper-links a:hover{background:var(--accent);color:white;border-color:var(--accent)}.why{align-self:start;border-top:5px solid var(--accent);padding:16px 0}.why span{font:500 9px var(--mono);letter-spacing:.1em;color:var(--accent)}.why p{font:600 14px/1.7 var(--sans);margin:10px 0}.why strong{font:500 34px var(--mono);color:var(--accent)}.access-note{font-size:11px;line-height:1.6;color:var(--muted);background:#e8e4db;padding:10px 12px}footer{background:var(--ink);color:white;min-height:220px;padding:52px clamp(24px,7vw,112px);display:grid;grid-template-columns:1fr 1fr auto;gap:40px;align-items:center}footer>div{display:flex;align-items:center;gap:16px}footer p{font:400 11px/1.8 var(--mono);color:#aaa}footer strong{font:700 16px var(--sans);color:white}footer a{color:white;font:500 11px var(--mono);text-decoration:none}.focus-mode .masthead,.focus-mode .priority,.focus-mode .section-nav,.focus-mode .section-head,.focus-mode footer,.focus-mode .why{display:none}.focus-mode .hero{min-height:100vh}.focus-mode .paper{grid-template-columns:52px minmax(0,850px);justify-content:center}.focus-mode .paper-section{padding-top:40px}.focus-mode .paper-section:not(.core){padding-top:0}\n@media(max-width:900px){.hero{grid-template-columns:1fr;padding-top:50px}.reading-map{transform:none;box-shadow:10px 10px 0 var(--core)}.priority{grid-template-columns:1fr}.priority>*{border-right:0;border-bottom:1px solid var(--ink)}.section-head{grid-template-columns:100px 1fr}.section-head>p{grid-column:2}.paper{grid-template-columns:42px minmax(0,1fr)}.why{grid-column:2}.section-nav a{font-size:11px}.section-nav span{display:none}}\n@media(max-width:600px){.masthead{height:68px;padding:0 18px}.issue{display:none}.hero{padding:50px 20px 64px;min-height:auto}.hero h1{font-size:54px}.dek{font-size:15px}.hero-actions{flex-direction:column}.primary,.ghost{justify-content:center}.reading-map{padding:22px}.map-head strong{font-size:50px}.priority>*{padding:22px 20px}.section-nav{overflow:auto;grid-template-columns:repeat(4,minmax(110px,1fr))}.paper-section{padding:0 20px 70px}.section-head{grid-template-columns:1fr;gap:14px;padding:46px 0}.section-head>p{grid-column:auto}.section-no{font-size:42px}.paper{grid-template-columns:1fr;gap:12px;padding:38px 0}.paper-index{display:none}.paper h3{font-size:27px}.plain{grid-template-columns:1fr;gap:6px;padding:16px}.plain p{font-size:15px}.metrics{grid-template-columns:1fr}.metrics div{border-right:0;border-bottom:1px solid var(--line)}.details-grid{grid-template-columns:1fr}.why{grid-column:auto}.paper-links{flex-wrap:wrap}footer{grid-template-columns:1fr;padding:42px 20px}.focus-mode .paper{grid-template-columns:1fr}.focus-mode .paper-section{padding-top:20px}}\n@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}\n\n/* Full-text review sheets */\n.review-loading{padding:20px 0;color:var(--muted);font-size:12px}\n.review-sheet{border-top:4px solid var(--accent);padding:0 0 8px;margin-bottom:22px}\n.review-kicker{display:flex;justify-content:space-between;gap:20px;align-items:center;background:var(--ink);color:white;padding:13px 16px}\n.review-kicker span{font:500 9px var(--mono);letter-spacing:.12em;color:var(--accent)}\n.review-kicker p{margin:0;font-size:10px;color:#aaa}\n.review-pair{display:grid;grid-template-columns:1fr 1fr;border:1px solid var(--line);border-top:0}\n.review-block{display:grid;grid-template-columns:34px 1fr;gap:12px;padding:22px 20px}\n.review-block+.review-block{border-left:1px solid var(--line)}\n.review-block>b,.review-title>b{font:500 10px var(--mono);color:var(--accent)}\n.review-block h4,.review-title h4,.review-bottom h4{font:700 14px var(--sans);margin:0 0 9px}\n.review-block p,.review-delta>p,.review-bottom p{font-size:13px;line-height:1.85;color:#45423c;margin:0}\n.review-contributions{border:1px solid var(--line);border-top:0;padding:22px 20px}\n.review-title{display:grid;grid-template-columns:34px auto 1fr;gap:12px;align-items:baseline}\n.review-title span{font:400 9px var(--mono);color:var(--muted);text-align:right}\n.review-contributions ol{list-style:none;margin:14px 0 0 46px;padding:0}\n.review-contributions li{display:grid;grid-template-columns:34px 1fr;gap:12px;padding:12px 0;border-top:1px solid var(--line)}\n.review-contributions li span{font:500 10px var(--mono);color:var(--accent);padding-top:3px}\n.review-contributions li p{margin:0;font-size:13px;line-height:1.75}\n.review-delta{background:color-mix(in srgb,var(--accent) 11%,transparent);border:1px solid var(--accent);padding:22px 20px}\n.review-delta>p{font-weight:600;font-size:14px;margin:14px 0 0 46px;color:var(--ink)}\n.review-pair.judgement{border-top:0}\n.review-block.evidence{background:#fff}\n.review-block.limitations{background:#e8e4db}\n.review-bottom{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line);border:1px solid var(--line);border-top:0}\n.review-bottom section{background:var(--paper);padding:20px}\n.review-bottom span{font:500 9px var(--mono);letter-spacing:.1em;color:var(--accent)}\n.review-bottom h4{margin-top:8px}\n\n@media(max-width:600px){\n  .review-pair,.review-bottom{grid-template-columns:1fr}\n  .review-kicker{align-items:flex-start;flex-direction:column}\n  .review-block+.review-block{border-left:0;border-top:1px solid var(--line)}\n  .review-title{grid-template-columns:28px 1fr}\n  .review-title span{grid-column:2;text-align:left}\n  .review-contributions ol{margin-left:0}\n  .review-delta>p{margin-left:0}\n}\n\n/* Permanent edition archive */\n.archive-link{color:inherit;text-decoration:none;border-bottom:1px solid currentColor;padding-bottom:2px}\n.archive-button{justify-content:center;color:var(--ink)}\n.archive-hero h1{font-size:clamp(48px,6.5vw,96px)}\n.archive-count{font:500 14px/2 var(--sans)!important;color:#d4d0c8!important;margin-top:36px!important}\n.archive-home{min-height:calc(100vh - 82px);padding:90px clamp(24px,7vw,112px);background:radial-gradient(circle at 80% 20%,rgba(141,92,246,.15),transparent 25%)}\n.archive-home h1{font:900 clamp(64px,9vw,132px)/.92 var(--display);letter-spacing:-.07em;margin:22px 0 32px}\n.archive-home h1 em{color:var(--landmark);font-style:normal}\n.archive-grid{margin-top:72px;border-top:5px solid var(--landmark)}\n.archive-card{display:grid;grid-template-columns:1.2fr .8fr .5fr auto;gap:24px;align-items:center;color:inherit;text-decoration:none;padding:28px 18px;border-bottom:1px solid var(--ink);transition:background .18s,color .18s}\n.archive-card:hover{background:var(--ink);color:white}\n.archive-card span,.archive-card b,.archive-card i{font:500 12px var(--mono);font-style:normal}\n.archive-card strong{font:700 20px var(--display)}\n.archive-card i{text-align:right}\n@media(max-width:600px){.archive-home{padding:60px 20px}.archive-grid{margin-top:48px}.archive-card{grid-template-columns:1fr auto}.archive-card strong,.archive-card b{grid-column:1}.archive-card i{grid-column:2;grid-row:1/4}}\n\n/* Reader feedback */\n.feedback-panel{margin-top:28px;border:1px solid var(--ink);background:#fff;padding:22px;box-shadow:7px 7px 0 color-mix(in srgb,var(--accent) 45%,transparent)}\n.feedback-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:28px;padding-bottom:16px;border-bottom:1px solid var(--line)}\n.feedback-heading span{font:500 9px var(--mono);letter-spacing:.12em;color:var(--accent)}\n.feedback-heading h4{font:700 17px var(--display);margin:5px 0 0}\n.feedback-heading p{font-size:10px;line-height:1.6;color:var(--muted);margin:0;max-width:290px}\n.feedback-signals{display:flex;flex-wrap:wrap;gap:8px;padding:16px 0}\n.feedback-signals button{border:1px solid var(--line);background:var(--paper);padding:9px 12px;font:600 11px var(--sans);cursor:pointer}\n.feedback-signals button:hover,.feedback-signals button.selected{background:var(--accent);border-color:var(--accent);color:white}\n.feedback-note{display:block}\n.feedback-note>span,.feedback-actions label span{display:block;font:500 9px var(--mono);letter-spacing:.08em;color:var(--muted);margin-bottom:7px}\n.feedback-note textarea{display:block;width:100%;resize:vertical;border:1px solid var(--line);background:#f8f6f0;color:var(--ink);padding:12px;font:400 13px/1.7 var(--sans)}\n.feedback-note textarea:focus,.feedback-actions select:focus{outline:2px solid var(--accent);outline-offset:1px}\n.feedback-actions{display:grid;grid-template-columns:160px auto 1fr;align-items:end;gap:12px;margin-top:12px}\n.feedback-actions select{width:100%;height:39px;border:1px solid var(--line);background:var(--paper);padding:0 8px;font:500 11px var(--sans)}\n.feedback-submit{height:39px;border:1px solid var(--ink);background:var(--ink);color:white;padding:0 16px;font:600 11px var(--sans);cursor:pointer}\n.feedback-submit:hover{background:var(--accent);border-color:var(--accent)}\n.feedback-submit:disabled{opacity:.55;cursor:wait}\n.feedback-status{font-size:11px;color:var(--muted);margin:0 0 9px}\n@media(max-width:600px){.feedback-panel{padding:17px;box-shadow:5px 5px 0 color-mix(in srgb,var(--accent) 45%,transparent)}.feedback-heading{display:block}.feedback-heading p{margin-top:8px}.feedback-actions{grid-template-columns:1fr}.feedback-status{margin:0}}\n"}};
const SIGNALS = new Set(['interested', 'more', 'less', 'question', 'ai_question']);
const SOURCES = new Set(['site', 'gemini', 'other']);

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {status, headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});
}

function userId(request) {
  return request.headers.get('oai-authenticated-user-id') || '';
}

function textContent(content) {
  return {content:[{type:'text',text:typeof content === 'string' ? content : JSON.stringify(content, null, 2)}]};
}

async function saveFeedback(request, env) {
  const user = userId(request);
  if (!user) return json({error:'需要通过 Research Daily 的私有访问身份提交反馈。'}, 401);
  let body;
  try { body = await request.json(); } catch { return json({error:'请求内容不是有效 JSON。'}, 400); }
  const paperId = String(body.paperId || '').trim().slice(0, 160);
  const title = String(body.title || '').trim().slice(0, 1000);
  const briefDate = String(body.briefDate || '').trim().slice(0, 32);
  const signal = String(body.signal || '').trim();
  const note = String(body.note || '').trim().slice(0, 4000);
  const source = String(body.source || 'site').trim();
  if (!paperId || !SIGNALS.has(signal) || !SOURCES.has(source)) return json({error:'反馈类型或论文标识无效。'}, 400);
  if ((signal === 'question' || source === 'gemini') && !note) return json({error:'问题反馈或 Gemini 片段不能为空。'}, 400);
  const result = await env.DB.prepare('INSERT INTO feedback (user_id,paper_id,paper_title,brief_date,signal,note,source) VALUES (?,?,?,?,?,?,?)')
    .bind(user,paperId,title,briefDate,signal,note,source).run();
  return json({saved:true,id:result.meta?.last_row_id ?? null}, 201);
}

async function readFeedback(request, env, args = {}) {
  const user = userId(request);
  if (!user) throw new Error('Authenticated Research Daily user required.');
  const paperId = String(args.paper_id || '').trim();
  const limit = Math.max(1, Math.min(Number(args.limit) || 100, 500));
  let statement;
  if (paperId) {
    statement = env.DB.prepare('SELECT id,paper_id,paper_title,brief_date,signal,note,source,created_at FROM feedback WHERE user_id=? AND paper_id=? ORDER BY created_at DESC,id DESC LIMIT ?').bind(user,paperId,limit);
  } else {
    statement = env.DB.prepare('SELECT id,paper_id,paper_title,brief_date,signal,note,source,created_at FROM feedback WHERE user_id=? ORDER BY created_at DESC,id DESC LIMIT ?').bind(user,limit);
  }
  const result = await statement.all();
  return result.results || [];
}

async function handleMcp(request, env) {
  let rpc;
  try { rpc = await request.json(); } catch { return json({jsonrpc:'2.0',id:null,error:{code:-32700,message:'Parse error'}}, 400); }
  const reply = (result) => json({jsonrpc:'2.0',id:rpc.id ?? null,result});
  if (rpc.method === 'server/discover') return reply({supportedVersions:['2026-07-28'],capabilities:{tools:{}}});
  if (rpc.method === 'tools/list') return reply({tools:[
    {name:'list_research_feedback',description:'Read the signed-in owner’s Research Daily feedback so future paper selection and summaries can adapt to their interests.',inputSchema:{type:'object',properties:{paper_id:{type:'string'},limit:{type:'integer',minimum:1,maximum:500}},additionalProperties:false}},
    {name:'record_external_questions',description:'Save only question excerpts the user explicitly chose to import from Gemini or another reading assistant. Never import an entire private conversation unless the user explicitly requests it.',inputSchema:{type:'object',required:['paper_id','questions'],properties:{paper_id:{type:'string'},paper_title:{type:'string'},brief_date:{type:'string'},questions:{type:'string',maxLength:4000},source:{type:'string',enum:['gemini','other']}},additionalProperties:false}}
  ]});
  if (rpc.method !== 'tools/call') return json({jsonrpc:'2.0',id:rpc.id ?? null,error:{code:-32601,message:'Method not found'}}, 404);
  const name = rpc.params?.name;
  const args = rpc.params?.arguments || {};
  try {
    if (name === 'list_research_feedback') return reply(textContent({feedback:await readFeedback(request,env,args)}));
    if (name === 'record_external_questions') {
      const synthetic = new Request(request.url,{method:'POST',headers:request.headers,body:JSON.stringify({paperId:args.paper_id,title:args.paper_title,briefDate:args.brief_date,signal:'ai_question',note:args.questions,source:args.source || 'gemini'})});
      const saved = await saveFeedback(synthetic,env);
      const payload = await saved.json();
      return reply({...textContent(payload),isError:!saved.ok});
    }
    return reply({...textContent('Unknown tool'),isError:true});
  } catch (error) {
    return reply({...textContent(error instanceof Error ? error.message : 'Tool failed'),isError:true});
  }
}

function serveAsset(pathname) {
  let path = decodeURIComponent(pathname);
  if (path.endsWith('/')) path += 'index.html';
  if (path === '') path = '/index.html';
  const asset = ASSETS[path];
  if (!asset) return new Response('Not found',{status:404});
  return new Response(asset.body,{headers:{'content-type':asset.type,'cache-control':asset.type.startsWith('text/html') ? 'no-cache' : 'public, max-age=300'}});
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === '/api/feedback' && request.method === 'POST') return saveFeedback(request,env);
    if (url.pathname === '/api/feedback' && request.method === 'GET') {
      try { return json({feedback:await readFeedback(request,env,{paper_id:url.searchParams.get('paper_id'),limit:url.searchParams.get('limit')})}); }
      catch (error) { return json({error:error.message},401); }
    }
    if (url.pathname === '/mcp' && request.method === 'POST') return handleMcp(request,env);
    if (request.method !== 'GET' && request.method !== 'HEAD') return new Response('Method not allowed',{status:405});
    return serveAsset(url.pathname);
  }
};
